import{_ as l,a0 as p,w as r,s as d,ao as o,I as n,x as s,a1 as a,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"如何隱藏你的 Linux 的命令列歷史 | LCTT x X-CMD","titleTemplate":false,"description":"如何隱藏你的 Linux 的命令列歷史 | LCTT (201607) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何隱藏你的 Linux 的命令列歷史 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何隱藏你的 Linux 的命令列歷史 | LCTT (201607) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201607/20160625 How to Hide Linux Command Line History by Going Incognito","title":"如何隱藏你的 Linux 的命令列歷史","tag":"201607","desc":""},"relativePath":"201607/20160625 How to Hide Linux Command Line History by Going Incognito.md","filePath":"[post].md"}'),h={name:"201607/20160625 How to Hide Linux Command Line History by Going Incognito.md"};function g(u,i,c,k,m,b){const e=p("Link");return r(),d("div",null,[i[16]||(i[16]=o('<h1 id="如何隱藏你的-linux-的命令列歷史" tabindex="-1">如何隱藏你的 Linux 的命令列歷史 <a class="header-anchor" href="#如何隱藏你的-linux-的命令列歷史" aria-label="Permalink to “如何隱藏你的 Linux 的命令列歷史”">​</a></h1><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/06/commandline-history-featured.jpg" alt=""></p><p>如果你是 Linux 命令列的用户，有的時候你可能不希望某些命令記錄在你的命令列歷史中。原因可能很多，例如，你在公司擔任某個職位，你有一些不希望被其它人濫用的特權。亦或者有些特別重要的命令，你不希望在你瀏覽歷史列表時誤執行。</p><p>然而，有方法可以控制哪些命令進入歷史列表，哪些不進入嗎？或者換句話説，我們在 Linux 終端中可以開啓像瀏覽器一樣的無痕模式嗎？答案是肯定的，而且根據你想要的具體目標，有很多實現方法。在這篇文章中，我們將討論一些行之有效的方法。</p><p>注意：文中出現的所有命令都在 Ubuntu 下測試過。</p><h3 id="不同的可行方法" tabindex="-1">不同的可行方法 <a class="header-anchor" href="#不同的可行方法" aria-label="Permalink to “不同的可行方法”">​</a></h3>',6)),n("p",null,[i[1]||(i[1]=s("前面兩種方法已經在之前",-1)),a(e,{href:"https://www.maketecheasier.com/command-line-history-linux/"},{default:t(()=>[...i[0]||(i[0]=[s("一篇文章",-1)])]),_:1}),i[2]||(i[2]=s("中描述了。如果你已經瞭解，這部分可以略過。然而，如果你不瞭解，建議仔細閲讀。",-1))]),i[17]||(i[17]=o('<h4 id="_1-在命令前插入空格" tabindex="-1">1. 在命令前插入空格 <a class="header-anchor" href="#_1-在命令前插入空格" aria-label="Permalink to “1. 在命令前插入空格”">​</a></h4><p>是的，沒看錯。在命令前面插入空格，這條命令會被 shell 忽略，也就意味着它不會出現在歷史記錄中。但是這種方法有個前提，只有在你的環境變量 <code>HISTCONTROL</code> 設置為 &quot;ignorespace&quot; 或者 &quot;ignoreboth&quot; 才會起作用。在大多數情況下，這個是默認值。</p><p>所以，像下面的命令（LCTT 譯註：這裏<code>[space]</code>表示輸入一個空格）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[space]echo &quot;this is a top secret&quot;</span></span></code></pre></div><p>如果你之前執行過如下設置環境變量的命令，那麼上述命令不會出現在歷史記錄中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>export HISTCONTROL = ignorespace</span></span></code></pre></div><p>下面的截圖是這種方式的一個例子。</p><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/06/commandline-history-bash-command-space.png" alt=""></p><p>第四個 &quot;echo&quot; 命令因為前面有空格，它沒有被記錄到歷史中。</p><h4 id="_2-禁用當前會話的所有歷史記錄" tabindex="-1">2. 禁用當前會話的所有歷史記錄 <a class="header-anchor" href="#_2-禁用當前會話的所有歷史記錄" aria-label="Permalink to “2. 禁用當前會話的所有歷史記錄”">​</a></h4><p>如果你想禁用某個會話所有歷史，你可以在開始命令列工作前簡單地清除環境變量 HISTFILESIZE 的值即可。執行下面的命令來清除其值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>export HISTFILESIZE=0</span></span></code></pre></div><p>HISTFILESIZE 表示對於 bash 會話其歷史文件中可以保存命令的個數（行數）。默認情況，它設置了一個非零值，例如在我的電腦上，它的值為 1000。</p><p>所以上面所提到的命令將其值設置為 0，結果就是直到你關閉終端，沒有東西會存儲在歷史記錄中。記住同樣你也不能通過按向上的箭頭按鍵或運行 history 命令來看到之前執行的命令。</p><h4 id="_3-工作結束後清除整個歷史" tabindex="-1">3. 工作結束後清除整個歷史 <a class="header-anchor" href="#_3-工作結束後清除整個歷史" aria-label="Permalink to “3. 工作結束後清除整個歷史”">​</a></h4><p>這可以看作是前一部分所提方案的另外一種實現。唯一的區別是在你完成所有工作之後執行這個命令。下面是剛説到的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>history -cw</span></span></code></pre></div><p>剛才已經提到，這個和 HISTFILESIZE 方法有相同效果。</p><h4 id="_4-只針對你的工作關閉歷史記錄" tabindex="-1">4. 只針對你的工作關閉歷史記錄 <a class="header-anchor" href="#_4-只針對你的工作關閉歷史記錄" aria-label="Permalink to “4. 只針對你的工作關閉歷史記錄”">​</a></h4><p>雖然前面描述的方法（2 和 3）可以實現目的，它們可以清除整個歷史，在很多情況下，有些可能不是我們所期望的。有時候你可能想保存直到你開始命令列工作之間的歷史記錄。對於這樣的需求，你開始在工作前執行下述命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[space]set +o history</span></span></code></pre></div><p>備註：[space] 表示空格。並且由於空格的緣故，該命令本身也不會被記錄。</p><p>上面的命令會臨時禁用歷史功能，這意味着在這命令之後你執行的所有操作都不會記錄到歷史中，然而這個命令之前的所有東西都會原樣記錄在歷史列表中。</p><p>要重新開啓歷史功能，執行下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[Space]set -o history</span></span></code></pre></div><p>它將環境恢復原狀，也就是你完成了你的工作，執行上述命令之後的命令都會出現在歷史中。</p><h4 id="_5-從歷史記錄中刪除指定的命令" tabindex="-1">5. 從歷史記錄中刪除指定的命令 <a class="header-anchor" href="#_5-從歷史記錄中刪除指定的命令" aria-label="Permalink to “5. 從歷史記錄中刪除指定的命令”">​</a></h4><p>現在假設歷史記錄中已經包含了一些你不希望記錄的命令。這種情況下我們怎麼辦？很簡單。直接動手刪除它們。通過下面的命令來刪除：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>history | grep &quot;part of command you want to remove&quot;</span></span></code></pre></div><p>上面的命令會輸出歷史記錄中匹配的命令，每一條前面會有個數字。</p><p>一旦你找到你想刪除的命令，執行下面的命令，從歷史記錄中刪除那個指定的項：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>history -d [num]</span></span></code></pre></div><p>下面是這個例子的截圖。</p><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2016/06/commandline-history-delete-specific-commands.png" alt=""></p><p>第二個 ‘echo’命令被成功的刪除了。</p><p>（LCTT 譯註：如果你不希望上述命令本身也被記錄進歷史中，你可以在上述命令前加個空格）</p><p>同樣的，你可以使用向上的箭頭一直往回翻看歷史記錄。當你發現你感興趣的命令出現在終端上時，按下 “Ctrl + U”清除整行，也會從歷史記錄中刪除它。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>有多種不同的方法可以操作 Linux 命令列歷史來滿足你的需求。然而請記住，從歷史中隱藏或者刪除命令通常不是一個好習慣，儘管本質上這並沒有錯。但是你必須知道你在做什麼，以及可能產生的後果。</p><hr>',40)),n("p",null,[i[4]||(i[4]=s("via: ",-1)),a(e,{href:"https://www.maketecheasier.com/linux-command-line-history-incognito/"},{default:t(()=>[...i[3]||(i[3]=[s("https://www.maketecheasier.com/linux-command-line-history-incognito/",-1)])]),_:1})]),n("p",null,[i[8]||(i[8]=s("作者：",-1)),a(e,{href:"https://www.maketecheasier.com/author/himanshu/"},{default:t(()=>[...i[5]||(i[5]=[s("Himanshu Arora",-1)])]),_:1}),i[9]||(i[9]=s(" 譯者：",-1)),a(e,{href:"https://github.com/chunyang-wen"},{default:t(()=>[...i[6]||(i[6]=[s("chunyang-wen",-1)])]),_:1}),i[10]||(i[10]=s(" 校對：",-1)),a(e,{href:"https://github.com/wxy"},{default:t(()=>[...i[7]||(i[7]=[s("wxy",-1)])]),_:1})]),n("p",null,[i[13]||(i[13]=s("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...i[11]||(i[11]=[s("LCTT",-1)])]),_:1}),i[14]||(i[14]=s(" 原創編譯，",-1)),a(e,{href:"https://linux.cn/"},{default:t(()=>[...i[12]||(i[12]=[s("Linux中國",-1)])]),_:1}),i[15]||(i[15]=s(" 榮譽推出",-1))])])}const C=l(h,[["render",g]]);export{y as __pageData,C as default};
